import { createHmac } from "node:crypto";
import { describe, expect, it } from "vitest";
import { verifyToken } from "../src/auth/jwt";

const SECRET = "s3cret";
const b64 = (o: unknown) => Buffer.from(JSON.stringify(o)).toString("base64url");

function sign(payload: unknown, header: unknown = { alg: "HS256", typ: "JWT" }, secret = SECRET) {
  const body = `${b64(header)}.${b64(payload)}`;
  return `${body}.${createHmac("sha256", secret).update(body).digest("base64url")}`;
}

const future = () => Math.floor(Date.now() / 1000) + 60;

describe("verifyToken", () => {
  it("accepts a validly signed, unexpired token", () => {
    const exp = future();
    expect(verifyToken(sign({ sub: "u1", exp }), SECRET)).toMatchObject({ sub: "u1", exp });
  });

  it("rejects a token signed with a different secret", () => {
    expect(() => verifyToken(sign({ sub: "u1", exp: future() }, undefined, "other"), SECRET)).toThrow();
  });

  it("rejects tampered claims", () => {
    const [h, , s] = sign({ sub: "u1", exp: future() }).split(".");
    expect(() => verifyToken(`${h}.${b64({ sub: "admin", exp: future() })}.${s}`, SECRET)).toThrow();
  });

  it("rejects alg=none forgeries", () => {
    const t = `${b64({ alg: "none" })}.${b64({ sub: "u1", exp: future() })}.`;
    expect(() => verifyToken(t, SECRET)).toThrow();
  });

  it("rejects expired tokens", () => {
    expect(() => verifyToken(sign({ sub: "u1", exp: 1 }), SECRET)).toThrow(/expired/);
  });

  it("rejects tokens missing exp", () => {
    expect(() => verifyToken(sign({ sub: "u1" }), SECRET)).toThrow();
  });
});

